SELECT 
FROM service_flash_price f
WHERE f.id=#{id}

SELECT COUNT(*) FROM service_flash_price
WHERE service_id=#{serviceId}
  AND status IN ('PENDING_REVIEW','SCHEDULED','ACTIVE','PAUSED')
  AND start_at < #{endAt}
  AND end_at > #{startAt}

  AND id != #{excludeId}

SELECT 
FROM service_flash_price f
WHERE f.service_id=#{serviceId}

  AND f.status=#{status}

ORDER BY f.created_at DESC, f.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM service_flash_price
WHERE service_id=#{serviceId}

  AND status=#{status}

SELECT , s.service_name
FROM service_flash_price f
LEFT JOIN service_item s ON s.id = f.service_id


      f.status=#{status}


ORDER BY f.updated_at DESC, f.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT s.id, s.merchant_id, s.store_id, s.service_name, s.price, s.status
FROM service_item s
WHERE s.id=#{serviceId}

SELECT 
FROM service_flash_price f
WHERE f.service_id=#{serviceId}
  AND f.status IN ('SCHEDULED','ACTIVE')
  AND f.start_at <= #{now}
  AND f.end_at > #{now}
ORDER BY f.start_at ASC, f.id ASC

SELECT COUNT(*) FROM service_flash_price_order
WHERE flash_price_id=#{flashPriceId} AND user_id=#{userId}
  AND status IN ('RESERVED','CONSUMED')

mapper.update:
UPDATE service_flash_price
SET sold_count=sold_count+1, version=version+1, updated_at=#{now}
WHERE id=#{id} AND version=#{expectedVersion}

mapper.select:
SELECT id, flash_price_id, order_id, user_id, reserved_price, status, expire_at,
       reserved_at, consumed_at, released_at, version
FROM service_flash_price_order
WHERE status='RESERVED' AND expire_at < #{cutoff}
ORDER BY expire_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE service_flash_price_order
SET status='RELEASED', released_at=#{now}, version=version+1
WHERE id=#{id} AND status='RESERVED' AND version=#{expectedVersion}

UPDATE service_flash_price
SET sold_count=sold_count-1, version=version+1, updated_at=#{now}
WHERE id=#{flashPriceId} AND sold_count > 0

UPDATE service_flash_price_command
SET status='SUCCEEDED', receipt_json=#{receiptJson}, updated_at=#{now}
WHERE request_key=#{requestKey}
